// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.newGrantProposal(actor, amount);
        uint256 afterFirst = c.proposalCount();
        vm.prank(actor);
        c.newGrantProposal(actor, amount);
        uint256 afterSecond = c.proposalCount();
        assertEq(afterSecond, afterFirst + 1);
    }
}
